#pragma once
#include "watchlist_reconciliation_model.hpp"
namespace watchlistHostAdapter {
using namespace watchlistWorkspace;
inline QJsonObject issue(QString reason,bool blocking,QJsonValue original=QJsonValue::Null){return {{"state","unverified"},{"reason",reason},{"blocking",blocking},{"original",original}};}
inline QJsonObject inputs(QJsonArray current,QJsonObject evidence){QJsonArray primary,main,legacy,issues;bool allowed=true;for(auto v:current){if(!v.isObject()){issues.append(issue("当前目录记录不是完整对象",true,v));allowed=false;continue;}auto row=v.toObject();if(row.contains("transient")&&!row.value("transient").isBool()){issues.append(issue("临时观察标记不是明确布尔值，未猜主自选身份",true,row.value("id")));allowed=false;}if(row.value("transient").toBool())continue;primary.append(row);main.append(row.value("id"));}QJsonObject in{{"instruments",primary},{"mainIds",main}};try{watchlistWorkspacePersistence::inputSnapshot(in,"host-input",{});}catch(const std::exception&e){issues.append(issue(QString::fromUtf8(e.what()),true));allowed=false;}
 if(evidence.value("nativeLocalSingletonContract").isBool()&&evidence.value("nativeLocalSingletonContract").toBool()){QHash<QString,int> at;auto colors=evidence.value("localColors").toObject();if(evidence.contains("localColors")&&!evidence.value("localColors").isObject()){issues.append(issue("本机旧识别色映射结构未核验",true,evidence.value("localColors")));allowed=false;}for(auto v:primary){auto row=v.toObject();if(!row.value("group").isString()||row.value("group").toString().isEmpty()){issues.append(issue("本机单组标签缺失，未凭名称或代码另造归属",true,row.value("id")));allowed=false;continue;}auto name=row.value("group").toString();if(!at.contains(name)){QJsonValue shade=colors.contains(name)?colors.value(name):QJsonValue("");at.insert(name,legacy.size());legacy.append(QJsonObject{{"name",name},{"color",shade},{"readOnly",false},{"memberIds",QJsonArray{}},{"sourceMeta",QJsonObject{{"projection","owned-native-single-group/v1"},{"field","group"},{"nativeLegacyLabel",name}}}});}int i=at.value(name);auto g=legacy[i].toObject();auto ms=g.value("memberIds").toArray();ms.append(row.value("id"));g["memberIds"]=ms;legacy.replace(i,g);}}else{issues.append(issue("未提供原生本机单组字段的明确合同，旧标签保持未核验",true));allowed=false;}
 if(!evidence.contains("importedGroups"))issues.append(issue("当前原生目录没有源只读组身份/来源/颜色；未推断外部导入组，须由宿主提供明确元数据",false));else if(!evidence.value("importedGroups").isArray()){issues.append(issue("导入只读组视图未核验",true,evidence.value("importedGroups")));allowed=false;}else for(auto v:evidence.value("importedGroups").toArray()){legacy.append(v);bool valid=v.isObject();auto g=v.toObject();QStringList missing;for(auto k:{"groupId","sourceId","name","color"})if(!g.value(k).isString()||(QString(k)!="color"&&g.value(k).toString().trimmed().isEmpty()))missing<<k;if(!g.value("readOnly").isBool()||!g.value("readOnly").toBool())missing<<"readOnly=true";if(!g.value("memberIds").isArray())missing<<"memberIds";if(!valid||!missing.isEmpty()){issues.append(issue("导入只读组缺明确字段："+missing.join(","),true,v));allowed=false;}}
 in["legacyGroups"]=legacy;try{watchlistWorkspacePersistence::project(in);}catch(const std::exception&e){issues.append(issue("首次旧组投影未核验："+QString::fromUtf8(e.what()),true,legacy));allowed=false;}if(!allowed)in.remove("legacyGroups");return {{"schema","watchlist-host-adapter/v1"},{"inputs",in},{"canInitialize",allowed},{"legacyGroupCandidates",legacy},{"issues",issues}};}
inline QJsonObject requireInputs(QJsonObject captured){need(captured.value("schema")=="watchlist-host-adapter/v1"&&captured.value("canInitialize").isBool()&&captured.value("canInitialize").toBool(),"首次本地组投影存在未核验原因，未部分初始化");return captured.value("inputs").toObject();}
inline QJsonObject initializationPreview(QJsonObject captured){auto in=requireInputs(captured);QJsonObject out{{"schema","watchlist-host-initialization-preview/v1"},{"rosterScope",watchlistReconciliation::scope(in)},{"legacyGroups",in.value("legacyGroups")},{"issues",captured.value("issues")}};out["fingerprint"]=hash(out);return out;}
inline void verifyInitialization(QJsonObject packet,QJsonObject result){need(packet.value("schema")=="watchlist-host-initialization-preview/v1"&&result.value("state")=="ready","初始投影回执未确认");auto scopeCopy=packet;auto fingerprint=text(scopeCopy,"fingerprint");scopeCopy.remove("fingerprint");need(hash(scopeCopy)==fingerprint,"初始化预览摘要失效");auto s=validate(result.value("snapshot").toObject());need(equal(watchlistReconciliation::scope({{"instruments",s.value("instruments")},{"mainIds",s.value("mainIds")}}),packet.value("rosterScope")),"初始投影主自选身份已变");auto expected=packet.value("legacyGroups").toArray(),actual=s.value("groups").toArray();need(expected.size()==actual.size(),"已有侧库投影与本次预览分组数量不同");for(int i=0;i<actual.size();i++){auto g=actual[i].toObject(),wanted=expected[i].toObject();if(!wanted.contains("groupId")){need(QRegularExpression("^local:[0-9a-f-]{36}$").match(g.value("groupId").toString()).hasMatch(),"本地组持久随机ID未确认");g.remove("groupId");}need(equal(g,wanted),"初始完整分组/来源/颜色回执不同，请重读已有侧库");}}
inline QJsonObject directory(QJsonObject storeResult,QString requested){need(storeResult.value("schema")=="watchlist-workspace-store-result/v1","分组侧库结果格式无效");auto state=text(storeResult,"state");need(state=="ready"||state=="needsReconciliation"||state=="uninitialized","分组侧库状态不支持");QJsonArray groups;QJsonObject c;if(state=="ready"){auto s=validate(storeResult.value("snapshot").toObject());c=watchlistWorkspacePersistence::config(s);}else if(state=="needsReconciliation")c=watchlistWorkspacePersistence::validateConfig(storeResult.value("config").toObject());groups=c.value("groups").toArray();QHash<QString,int> same;for(auto v:groups)same[v.toObject().value("name").toString()]++;QJsonArray options{QJsonObject{{"groupId",""},{"name","全部自选"},{"displayName","全部自选"},{"color",""},{"readOnly",true},{"memberIds",QJsonArray{}}}};QString selected="",selectedName="全部自选";QJsonArray members;for(auto v:groups){auto g=v.toObject();auto name=text(g,"name"),id=text(g,"groupId");g["displayName"]=same.value(name)>1?name+" · "+id:name;g["memberCount"]=g.value("memberIds").toArray().size();options.append(g);if(id==requested){selected=id;selectedName=name;members=g.value("memberIds").toArray();}}return {{"schema","watchlist-host-directory/v1"},{"state",state},{"options",options},{"selectedGroupId",selected},{"selectedName",selectedName},{"memberIds",members},{"requiresReconciliation",state=="needsReconciliation"}};}
inline bool includes(QJsonObject directory,QString full){need(directory.value("schema")=="watchlist-host-directory/v1"&&fullId(full),"目录或完整证券身份无效");return directory.value("selectedGroupId").toString().isEmpty()||directory.value("memberIds").toArray().contains(full);}
inline QString diagnostics(QJsonObject capture){QStringList out;for(auto v:capture.value("issues").toArray())out<<v.toObject().value("reason").toString();return out.join('\n');}
}
